-- 007: simplified tags and traits (Tank, Support/healer, Camouflage; no anti-tank/rush/slow-teamfight/cleanse/anti-walking),
-- wave clear merged into high-ground defense, sustain-dive and split-vs-front-to-back rules, global presence bonus. Safe to re-run.

update hero_profiles set ratings = ratings - 'wave_clear' where ratings ? 'wave_clear';

update hero_profiles h set tags = v.tags, strong_vs_traits = v.s, weak_vs_traits = v.w, good_with_traits = v.g, notes = v.notes
from (values
  ('aamon', array['pickoff', 'stealth']::text[], array['immobile']::text[], array[]::text[], array[]::text[], 'Strong mid to late game, weak early. No dash, but camouflage is very strong in lower ranks; higher ranks can dodge his ultimate with dashes and Flicker (not easy). Easy to play but timing matters. Strong against immobile heroes and heroes that rely on targeting (camouflage). Recommended jungle pick against front-to-back drafts with an immobile backline. Close to meta (A tier).'),
  ('akai', array[]::text[], array[]::text[], array[]::text[], array[]::text[], 'Very recommended against certain drafts, e.g. Aulus, Lukas and dive comps — easily disrupts them. Very strong high-ground defense. Not naturally a frontline. Falls off late due to long cooldowns and more mobile enemies. Strong invade: built-in dash + stun at levels 1–2 for pickoffs. Weak to Purify and CC immunity (Diggie). Lesley is the best anti-tank into him; Karrie, X.Borg and Dyrroth get spun by his ultimate.'),
  ('aldous', array['pickoff', 'split']::text[], array[]::text[], array[]::text[], array[]::text[], 'Out of meta — too immobile, hard to make viable. Plays as an assassin finisher from the EXP lane. Very weak early. Late game easily bursts far-back squishies (Lesley, Layla) but needs good timing. Split push is strong and must be respected, but leaves the team without an EXP frontline. Countered by defensive items and teams that stick together.'),
  ('alice', array['thick']::text[], array['thick']::text[], array['anti_heal', 'cc', 'mobility']::text[], array[]::text[], 'S tier with Angela, A tier without; in the meta. Sustain teamfighter, front-to-back. Easily kited early; scales hard late. Weak to anti-heal (Baxia), crowd control and kiting heroes (Karrie, Lunox). Strong against tanky EXP fighters and fighter gold laners. Alpha can win early but Alice mostly out-sustains him late. Franco''s suppress is strong before Alice stacks. Lower ranks have a harder time against her.'),
  ('alpha', array['dive', 'pickoff', 'true_damage']::text[], array['thick']::text[], array[]::text[], array[]::text[], 'Strong against Belerick, Carmilla and tank-heavy drafts (true damage). Falls off late. Pickoff/dive, all-in commit — can''t really poke. Must land his ultimate. Estes is a strong counter.'),
  ('alucard', array[]::text[], array[]::text[], array['cc', 'anti_heal']::text[], array[]::text[], 'Decent against certain drafts: strong sustain and damage against enemies without stuns (lifesteal). Bad against drafts with stunners. If he gets ahead early he snowballs very hard and farms very fast. Weak to anti-heal, hard crowd control and kiting. Much stronger in low ranks and solo queue (uncoordinated teams).'),
  ('angela', array['enchanter', 'global']::text[], array[]::text[], array[]::text[], array[]::text[], 'C tier — very conditional, usually not good. Works with Alice or Lukas, or high-skill assassins that go in and out with burst: Lancelot, Gusion and Hayabusa are most viable, Yi Sun-shin and Nolan possible. Without tank/sustain heroes she leaves the marksman in a very bad state. Global presence is one of her biggest advantages. Pickoff comes from her ultimate.'),
  ('argus', array['split', 'thick']::text[], array['thick']::text[], array['mobility']::text[], array[]::text[], 'Very situational, B tier (A if played right). Good against burst (Kadita, Eudora, Tigreal combos that usually delete a solo target). Stays in long drawn-out teamfights and is a very good split pusher. Generally wins fights against tanks. Weak against kiters that run away (Chang''e, Lesley, Granger, Beatrix); needs the team to back him up, otherwise he split pushes. Team dependent.'),
  ('arlott', array['dive', 'pickoff']::text[], array[]::text[], array['lockdown']::text[], array['cc']::text[], 'Very strong — S tier if played correctly. Like Lancelot but stronger, and has crowd control too. Not a frontliner but huge damage; overwhelms enemies and makes a mess. Falls off late. Strong against teams without lockdown. Synergy with crowd-control allies. Can still deal with split pushers if played right. Usually builds lifesteal, so bring anti-heal. Countered by Phoveus (cancels dashes, out-sustains, teleports), Minsitthar and Khufra (dash cancels), Kaja (lockdown).'),
  ('atlas', array['thick']::text[], array[]::text[], array[]::text[], array[]::text[], 'Very strong presence (CC ultimate control) but doesn''t need a ban.'),
  ('aulus', array['dive', 'thick']::text[], array[]::text[], array[]::text[], array[]::text[], 'Counter with early pressure and kiting — little escape.'),
  ('aurora', array[]::text[], array[]::text[], array[]::text[], array[]::text[], ''),
  ('badang', array[]::text[], array[]::text[], array[]::text[], array[]::text[], ''),
